  renderDayBase();const tabs=$("#day-tabs");
  if(!$("#add-day-button")){const add=document.createElement("button");add.type="button";add.className="day-tab add-day-tab";add.id="add-day-button";add.textContent="＋ 日程を追加";tabs.append(add);add.addEventListener("click",addDay)}
  const title=$("#day-content .day-title-row"),tools=document.createElement("div");tools.className="day-tools";tools.innerHTML='<button type="button" class="add-event-button">＋ 予定を追加</button><button type="button" class="remove-day-button">日程を削除</button>';
  if(activeDay>0)tools.insertAdjacentHTML("afterbegin",'<button type="button" class="copy-previous-day">前日をコピー</button>');title.append(tools);tools.querySelector(".copy-previous-day")?.addEventListener("click",copyPreviousDay);tools.querySelector(".add-event-button").addEventListener("click",addEvent);tools.querySelector(".remove-day-button").addEventListener("click",removeDay);
  const day=trip.days[activeDay],list=$("#event-list");if(day.summary)$("#day-content .day-title-row p").textContent=day.summary;if(!day.events.length)list.innerHTML='<p class="empty-day">予定はまだありません。「＋ 予定を追加」から自由に追加できます。</p>';
